-- ---------------------------------------------------------------------------
-- Poses
-- ---------------------------------------------------------------------------

local function rotation(values, at: number): CFrame
	local v = Vector3.new(values[at], values[at + 1], values[at + 2])
	local angle = v.Magnitude
	return if angle < 1e-4 then CFrame.identity else CFrame.fromAxisAngle(v / angle, angle)
end

local function scaled(cf: CFrame, weight: number): CFrame
	if weight == 1 then
		return cf
	end
	local axis, angle = cf:ToAxisAngle()
	return if angle < 1e-4 then CFrame.identity else CFrame.fromAxisAngle(axis, angle * weight)
end

local CHANNELS = { core = 4, hood = 7, left = 10, right = 13 }

-- Decoded once per clip: per frame, each channel as a CFrame relative to the
-- stance, and the root's lift.
local decoded = {}
local function frames(name: string)
	local cached = decoded[name]
	if cached then
		return cached
	end
	local clip = Clips.Data[name]
	local raw = clip.frames
	local stance = if clip.stance == "first" then raw else STANCE
	local inverse = {}
	for channel, at in CHANNELS do
		inverse[channel] = rotation(stance, at):Inverse()
	end
	local list = {}
	for index = 0, #raw / 15 - 1 do
		local base = index * 15
		local frame = { lift = (raw[base + 2] - stance[2]) * WEIGHT.lift }
		for channel, at in CHANNELS do
			local relative = rotation(raw, base + at) * inverse[channel]
			if channel == "core" then
				local x, y, z = relative:ToEulerAnglesYXZ()
				frame.core = CFrame.fromEulerAnglesYXZ(x * WEIGHT.core, y * WEIGHT.coreYaw, z * WEIGHT.core)
			else
				frame[channel] = scaled(relative, WEIGHT[channel])
			end
		end
		list[index + 1] = frame
	end
	decoded[name] = list
	return list
end

--[[
	The pose at clip time `t`: { core, hood, left, right } as CFrames for each
	joint's Transform (the core also lifts or sinks with the clip's root), and
	slerped between baked frames.
]]
function Clips.pose(name: string, t: number)
	local list = frames(name)
	local f = math.clamp(t * Clips.Rate, 0, #list - 1)
	local index = math.floor(f)
	local a = list[index + 1]
	local b = list[math.min(index + 2, #list)]
	local alpha = f - index
	local lift = a.lift + (b.lift - a.lift) * alpha
	return {
		core = CFrame.new(0, lift, 0) * a.core:Lerp(b.core, alpha),
		hood = a.hood:Lerp(b.hood, alpha),
		left = a.left:Lerp(b.left, alpha),
		right = a.right:Lerp(b.right, alpha),
	}
end

-- ---------------------------------------------------------------------------
-- Timelines
-- ---------------------------------------------------------------------------

--[[
	A plan for one playback. Options: windup (seconds from the start to the
	Swing marker; default authored), hold (seconds frozen at Hit; default 0,
	math.huge for "until something else plays"), speed (everything that is
	not windup or hold; default 1), from (clip time to start at; default 0).
]]
function Clips.plan(name: string, options)
	local clip = Clips.Data[name]
	assert(clip, "Unknown Signus clip " .. tostring(name))
	options = options or {}
	local speed = options.speed or 1
	local from = math.clamp(options.from or 0, 0, clip.length)
	local swing = math.max(clip.markers.Swing or from, from)
	local hit = math.max(clip.markers.Hit or swing, swing)
	local reset = math.max(clip.markers.Reset or clip.length, hit)
	local windup = options.windup or (swing - from) / speed
	local release = (hit - swing) / speed
	local hold = options.hold or 0
	local plan = {
		name = name, from = from, swing = swing, hit = hit, reset = reset, length = clip.length,
		windup = math.max(windup, 0), release = release, hold = hold, speed = speed,
	}
	-- Seconds after the start at which each marker is reached.
	plan.marks = {
		swing = plan.windup,
		hit = plan.windup + release,
		resume = plan.windup + release + hold,
		reset = plan.windup + release + hold + (reset - hit) / speed,
		finish = plan.windup + release + hold + (clip.length - hit) / speed,
	}
	return plan
end

-- The clip time `elapsed` seconds into a plan, and whether it has finished.
function Clips.clipTime(plan, elapsed: number): (number, boolean)
	local marks = plan.marks
	if elapsed < marks.swing then
		local a = if plan.windup > 0 then elapsed / plan.windup else 1
		return plan.from + (plan.swing - plan.from) * a, false
	elseif elapsed < marks.hit then
		return plan.swing + (elapsed - marks.swing) * plan.speed, false
	elseif elapsed < marks.resume then
		return plan.hit, false
	end
	local t = plan.hit + (elapsed - marks.resume) * plan.speed
	return math.min(t, plan.length), t >= plan.length
end

-- The attribute form: name;serverStart;windup;hold;speed;from.
function Clips.encode(plan, startedAt: number): string
	local hold = if plan.hold == math.huge then -1 else plan.hold
	return string.format("%s;%.3f;%.3f;%.3f;%.3f;%.3f", plan.name, startedAt, plan.windup, hold, plan.speed, plan.from)
end

function Clips.decode(text: string?)
	if type(text) ~= "string" then
		return nil
	end
	local name, started, windup, hold, speed, from = string.match(text, "^(%w+);([%d%.%-]+);([%d%.%-]+);([%d%.%-]+);([%d%.%-]+);([%d%.%-]+)$")
	if not name or not Clips.Data[name] then
		return nil
	end
	local holdValue = tonumber(hold)
	local plan = Clips.plan(name, {
		windup = tonumber(windup), hold = if holdValue and holdValue < 0 then math.huge else holdValue,
		speed = tonumber(speed), from = tonumber(from),
	})
	return plan, tonumber(started)
end

return Clips
